from h34 import *
import math
M=mcq;F=tf;S=short;N=num
def clock(cx,h,m,label):
    r=90;o=f'<circle cx="{cx}" cy="130" r="{r}" fill="#fffbe6" stroke="#222" stroke-width="4"/>'
    for i in range(12):
        a=math.radians(i*30);x=cx+(r-14)*math.sin(a);y=130-(r-14)*math.cos(a)
        o+=f'<text x="{x:.1f}" y="{y+5:.1f}" text-anchor="middle" font-size="15" font-weight="bold">{12 if i==0 else i}</text>'
    ah=math.radians(h%12*30+m/2);am=math.radians(m*6)
    o+=f'<line x1="{cx}" y1="130" x2="{cx+48*math.sin(ah):.1f}" y2="{130-48*math.cos(ah):.1f}" stroke="#222" stroke-width="7" stroke-linecap="round"/>'
    o+=f'<line x1="{cx}" y1="130" x2="{cx+72*math.sin(am):.1f}" y2="{130-72*math.cos(am):.1f}" stroke="#d1495b" stroke-width="4" stroke-linecap="round"/><circle cx="{cx}" cy="130" r="5" fill="#222"/>'
    o+=f'<text x="{cx}" y="248" text-anchor="middle" font-size="16">{label}</text>'
    return o
b='<text x="360" y="24" text-anchor="middle" font-size="18" font-weight="bold">Same clock face, different time of day</text>'
b+=clock(130,8,0,"8:00 AM = 08:00 (morning)")+clock(360,8,20,"8:20 (short hand near 8)")+clock(590,8,0,"8:00 PM = 20:00 (night)")
svgfile('c4m-clock-ampm.svg',720,270,b)
chapter(4,'maths','ticking-clocks-and-turning-calendar','Ticking Clocks and Turning Calendar',
 ('Parv has a very special birthday!','Parv was born on 29 February 2016, a date that comes only once in four years. Today he is celebrating with his friends. In this chapter we learn about leap years, days and dates, reading a calendar, AM and PM, the 24-hour digital clock, and how much time activities take.'),
 [('Leap years and February',['Parv says he was born on 29 February 2016. Years that have a 29 February are called leap years.','Most years have 365 days. A leap year has one extra day, so it has 366 days.','Look at the February pages of the calendar. February 2024 has 29 days, so 2024 is a leap year. February 2025 has only 28 days, so it is not.','A leap year comes once in every four years. The leap years before and after 2024 are 2020 and 2028, and then 2032.']),
  ('Days of the week and dates',['A week has seven days, and they come in the same order again and again: Sunday, Monday, Tuesday, Wednesday, Thursday, Friday and Saturday.','If today is Wednesday, then yesterday was Tuesday, tomorrow is Thursday, the day after tomorrow is Friday and the day before yesterday was Monday.','If 1 July is a Monday, the next Mondays are 8 July and 15 July, because the same weekday comes back after every 7 days.','So to find the weekday of a date, we can count in sevens from a date whose day we know.']),
  ('Reading dates and finding who is older',['Dates can be written as day, month and year. 04/07/2024 is read as the 4th of July 2024, in the DD/MM/YYYY style.','Laali was born on 04/07/2014 and Chotu on 04/12/2019. Laali was born earlier, so Laali is older.','From 4 July 2014 to 4 July 2019 is 5 years, and from July to December is 5 more months, so Laali is 5 years and 5 months older than Chotu.','Laali turned 5 on 04/07/2019 and Chotu will turn 10 on 04/12/2029.']),
  ('Manufacture and expiry dates',['Packets of biscuits show the date of manufacture and the date of expiry. The manufacture date tells when it was made.','The expiry date tells the last day we can safely eat it. After that day the food may spoil.','To find how old a packet is we count from the manufacture date to today, and to find how long it stays safe we count from today to the expiry date.','Always check the expiry date before buying or eating packed food.']),
  ('Patterns in the calendar and other calendars',['Notice the day on which 15 July falls. Look at 15 August, 15 September and 15 October. The weekday moves ahead each month because months have 30 or 31 days, and 30 days is 4 weeks and 2 days.','In many communities, there are other calendars, like the Hindu, Islamic and Sikh calendars, whose months follow the moon.','Ask your parents or teacher when the year begins in your community’s calendar, and which months have big festivals.','In these calendars the new moon day and full moon day come about once in a month, and they have special names.']),
  ('Hours in a day',['A day has 24 hours. The picture of the doctor’s day shows hours spent on waking up, going to the hospital, working, resting, cooking and sleeping.','If you add the hours from 6 in the morning to 6 in the evening, you get 12 hours, and the next 12 hours bring us to 6 in the morning again.','So 12 hours plus 12 hours make 24 hours, one full day.']),
  ('AM, PM and the digital clock',['The clock can show 8:00 in the morning and 8:00 at night. To tell them apart we write AM for time from midnight to noon and PM for time from noon to midnight.','So 8:00 AM is morning, and 8:00 PM is night time.','A 24-hour digital clock does not need AM or PM. Midnight is 00:00, and after noon it goes 13:00, 14:00 and so on up to 23:59.','To change PM time to 24-hour time we add 12 hours. So 3:00 PM is 15:00, 5:20 PM is 17:20, and 8:00 PM is 20:00. Time before noon stays the same, so 9:45 AM is 09:45.']),
  ('Hours, minutes and half and quarter hours',['One hour has 60 minutes. Half an hour is 30 minutes and a quarter of an hour is 15 minutes.','Raghav leaves home at 8:20 and comes back at 8:35, so he takes 15 minutes, a quarter of an hour.','To show a time after some minutes, we move the minute hand forward. 25 minutes after 10:20 is 10:45, and 45 minutes after 4:15 is 5:00.','If Akira leaves at 8:00 and reaches school in 15 minutes, she gets there at 8:15. One hour is 60 minutes, so 8:00 to 9:00 is 60 minutes.']),
  ('Reading a clock correctly',['The short hand shows hours and the long hand shows minutes. When the long hand is on 4, that is 20 minutes, because each number is 5 minutes.','Raghu read the clock as 12:04, Raghav as 12:20 and Rani as 04:00. Raghav is right because the long hand is on the 4, meaning 20 minutes.','Raghu counted 4 as 4 minutes instead of 20, and Rani mixed up the two hands.','Always check the short hand for the hour first, and then count in fives with the long hand.'])],
 [('Raghav started homework at 10:20 AM and took 25 minutes. When did he finish?',[('Start at 10:20 and add 25 minutes.','Minutes go from 20 to 45 in this case.'),('20 + 25 = 45 minutes, which is less than 60, so the hour does not change.','The hour stays 10.'),('He finished at 10:45 AM.','Check: from 10:20 to 10:45 is 25 minutes.')]),
  ('Convert 5:20 PM to the 24-hour digital clock.',[('It is PM, so we add 12 to the hour.','PM times after noon add 12.'),('5 + 12 = 17, and the minutes stay the same, 20.','Minutes do not change.'),('So 5:20 PM is 17:20 hours.','Check: 17:20 is after noon, so it matches PM.')])],
 ('Explain how to read a time on a clock and write it in AM or PM and 24-hour form.',['Read the hour from the short hand and the minutes from the long hand','Count in fives from 12 for the minutes','Say AM for before noon and PM for after noon','Add 12 to PM hours to get 24-hour time'],['The long hand shows the hour','Each number on the clock is 1 minute','A leap year has 365 days']),
 ['A leap year has 366 days, with 29 February, and comes every 4 years.','The weekday of a date repeats after every 7 days.','AM is before noon and PM is after noon; 24-hour time adds 12 to PM hours.','60 minutes make an hour, 30 a half hour and 15 a quarter hour.','On a clock the short hand shows hours and the long hand shows minutes counted in fives.'],
 [M('1',1,'How many days does a leap year have?','366',[('365','That is a normal year'),('364','No year has 364 days')],'A leap year has an extra day, 29 February.'),
  M('2',1,'How many minutes are in a quarter of an hour?','15',[('30','30 minutes is half an hour'),('45','45 is three quarters of an hour')],'60 ÷ 4 = 15.'),
  M('3',1,'Which time is written in the AM?','7:15 in the morning',[('7:15 at night','Night time is PM'),('3:00 in the afternoon','Afternoon is PM')],'AM is from midnight to noon.'),
  M('4',1,'Which year is a leap year?','2024',[('2025','February 2025 had only 28 days'),('2023','It is not 4 years from 2024 in the pattern')],'Leap years come every 4 years: 2020, 2024, 2028.'),
  M('5',2,'What is 3:00 PM on a 24-hour clock?','15:00',[('13:00','13:00 is 1:00 PM'),('03:00','That is 3:00 AM, early morning')],'Add 12: 3 + 12 = 15.'),
  M('6',2,'If 1 July is a Monday, 15 July is a ___.','Monday',[('Sunday','15 − 1 = 14 days = 2 weeks, so the same day'),('Tuesday','Two whole weeks bring the same weekday')],'Every 7 days the weekday repeats.'),
  M('7',2,'A girl reads for 45 minutes starting at 4:15 PM. When does she finish?','5:00 PM',[('4:45 PM','That is only 30 minutes'),('5:15 PM','That is 60 minutes')],'4:15 plus 45 minutes is 5:00.'),
  M('8',2,'Laali was born on 04/07/2014 and Chotu on 04/12/2019. Who is older?','Laali',[('Chotu','Chotu was born 5 years later'),('Both are the same age','The years are different')],'The earlier birth date means older.'),
  N('9',2,'How many minutes are there from 8:20 to 8:35?',15,'35 − 20 = 15.',[(55,'That adds the numbers instead of finding the difference'),(25,'Count from 20 to 35, not from 10')],'minutes'),
  M('10',2,'The long hand is on 4 and the short hand just past 12. The time is ___.','12:20',[('12:04','Each number on the clock is 5 minutes, not 1'),('4:00','That would put the short hand on 4')],'4 × 5 = 20 minutes.'),
  F('11',2,'12:00 midnight is written 00:00 on a 24-hour clock.',True,'The day starts at 00:00.'),
  F('12',3,'30 days make 4 weeks and 2 days.',True,'4 × 7 = 28, and 30 − 28 = 2.')],
 svgs=[('c4m-clock-ampm','Three clocks: 8 o’clock in the morning, 8:20 and 8 o’clock at night.','The same clock face shows morning and night; we use AM, PM and a 24-hour clock to tell them apart.')],
 keep=['leap year','AM','PM','calendar'])
